-- Read-only dry-run SAIF v0.26A.1.8
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @offline_session_key := _utf8mb4'ecbbfa867b491c93570b92e0c6d3ff34e1e916da9df914d83edb066c1eac52c3' COLLATE utf8mb4_unicode_ci;
SET @session_id := (SELECT id FROM offline_import_sessions WHERE session_key COLLATE utf8mb4_unicode_ci = @offline_session_key COLLATE utf8mb4_unicode_ci LIMIT 1);
SELECT sp.id,p.display_name,p.context_type,p.pair_group_key,p.interior_id,sp.service_x,sp.service_y,sp.service_z,sp.service_a,sp.service_radius,sp.interaction_semantics,sp.resolution_method,sp.confidence,sp.review_status,p.apply_readiness FROM offline_interior_service_points sp JOIN offline_interior_apply_plan p ON p.id=sp.plan_id WHERE sp.session_id=@session_id AND sp.resolver_version='saif_service_point_resolver_v0.26A.1.8' ORDER BY FIELD(sp.resolution_method,'saif_overlay_translated','scm_exact'),p.context_type,p.pair_group_key,p.area_code;
SELECT p.context_type,p.pair_group_key,COUNT(*) plans,sp.service_x,sp.service_y,sp.service_z,sp.resolution_method,sp.review_status FROM offline_interior_apply_plan p JOIN offline_interior_service_points sp ON sp.id=p.service_point_id WHERE p.session_id=@session_id AND p.plan_version='saif_enex_pair_planner_v0.26A.1.7' GROUP BY p.context_type,p.pair_group_key,sp.service_x,sp.service_y,sp.service_z,sp.resolution_method,sp.review_status ORDER BY p.context_type,p.pair_group_key;
